window.CANTON_140_B64 = "";
window.loadCanton140Catalog = async function() {
  if (window.CANTON_140_RECORDS && window.CANTON_140_RECORDS.length > 0) return window.CANTON_140_RECORDS;
  try {
    const binaryStr = atob(window.CANTON_140_B64);
    const bytes = new Uint8Array(binaryStr.length);
    for (let i = 0; i < binaryStr.length; i++) {
      bytes[i] = binaryStr.charCodeAt(i);
    }
    const stream = new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip')));
    const text = await stream.text();
    window.CANTON_140_RECORDS = JSON.parse(text);
    console.log("🟢 Catálogo Cantón 140 descomprimido:", window.CANTON_140_RECORDS.length, "registros.");
    return window.CANTON_140_RECORDS;
  } catch(e) {
    console.error("Error al descomprimir catálogo Cantón 140:", e);
    return [];
  }
};
